package com.hbm.client.radar;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.machine.radar.*;import java.util.Arrays;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.resources.language.I18n;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.network.chat.Component;import net.minecraft.network.protocol.game.ServerboundContainerClosePacket;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.entity.player.Inventory;
/** Source176x18410slot GUI and cursor-preserving transition back to the radar screen. */
public final class RadarInventoryScreen extends LegacyContainerScreen<RadarMenu>{private boolean switching;public RadarInventoryScreen(RadarMenu menu,Inventory player,Component title){super(menu,player,title,RadarContent.id("textures/gui/machine/gui_radar_link.png"),176,184);}@Override protected void renderLabels(GuiGraphics g,int x,int y){Component title=com.hbm.LegacyStartup.polaroidId==11?Component.literal("Reda"):this.title;g.drawString(font,title,88-font.width(title)/2,6,4210752,false);g.drawString(font,playerInventoryTitle,8,90,4210752,false);}@Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);if(menu.machine!=null&&menu.machine.power>0)drawLegacyRegion(g,8,64,0,185,(int)(menu.machine.power*160/menu.machine.getMaxPower()),16);}@Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);if(legacyInfoHovered(x,y,5,5,8,8))g.renderComponentTooltip(font,Arrays.stream(I18n.get("radar.toggleGui").split(java.util.regex.Pattern.quote("$"),-1)).map(Component::literal).map(c->(Component)c).toList(),x,y);}@Override public boolean mouseClicked(double x,double y,int button){boolean result=super.mouseClicked(x,y,button);if(legacyInfoHovered(x,y,5,5,8,8)&&menu.machine!=null){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));switching=true;minecraft.player.connection.send(new ServerboundContainerClosePacket(menu.containerId));minecraft.player.containerMenu=minecraft.player.inventoryMenu;minecraft.setScreen(new RadarScreen(menu.machine));return true;}return result;}@Override public void removed(){if(!switching)super.removed();}}
